# -*- coding: utf-8 -*-
from taf.playwright.sbts.common.basic_page import PlaywrightBasicPage


class BtsStatusPage(PlaywrightBasicPage):
    """Minimal BTS status reader.

    The selectors are intentionally conservative for the first Playwright backend
    skeleton. Product teams can replace them with stable role/test-id selectors
    after validating the real SBTS page.
    """

    STATUS_CANDIDATES = (
        '[data-testid="bts-status"]',
        '[name="bts-status"]',
        '.bts-status',
        'text=/BTS Status/i',
    )

    TECHNOLOGY_STATUS = (
        '//div[contains(normalize-space(.), "{technology}")]/preceding-sibling::div',
        '//div[contains(normalize-space(.), "{technology}")]/parent::*//*[contains(@class, "status")]',
        'text=/{technology}/i',
    )

    def get_status(self, timeout=5, technology=None):
        if technology:
            for selector in self._technology_candidates(technology):
                if self.is_visible(selector, timeout=1):
                    return self.text(selector, timeout)
        for selector in self.STATUS_CANDIDATES:
            if self.is_visible(selector, timeout=1):
                return self.text(selector, timeout)
        return self.page.title()

    def _technology_candidates(self, technology):
        safe_technology = str(technology).replace('"', '\\"')
        return [selector.format(technology=safe_technology) for selector in self.TECHNOLOGY_STATUS]
